                    { 2304, "Common", "faculty_science", "7.5.2 / 7.5.3", 472, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النماذج السارية ← الفهرسة والأرشفة الآمنة ← مدة الحفظ : التحقق من التزام العمادة والأقسام الأكاديمية بضبط الوثائق وحفظ السجلات (محاضر المجالس، ملفات المساقات، ملفات الإرشاد) وفق نظام الجودة." },
                    { 2305, "Common", "faculty_science", "7.2", 473, "التدريب والكفاءة", "حصر الاحتياجات التدريبية (للكادر الأكاديمي والإداري والفني) ← خطة التدريب ← المشاركة الفعلية ← قياس أثر التدريب : التحقق من تأهيل وتدريب أعضاء هيئة التدريس ومشرفي المختبرات والإداريين في الكلية وتقييم انعكاس التدريب على أدائهم." },
                    { 2306, "Common", "faculty_science", "6.2", 474, "هدف الجودة", "صياغة أهداف ذكية للكلية والأقسام ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للكلية ومنسجمة مع أهداف الجامعة، ومتابعة نسب تحققها." },
                    { 2307, "Common", "faculty_science", "4.1 / 6.2", 475, "الخطة الاستراتيجية", "إعداد خطة الكلية الاستراتيجية المتوافقة مع استراتيجية الجامعة ← الاعتماد ← المراجعة الدورية : التحقق من وجود خطة استراتيجية معتمدة للكلية تنبثق من الخطة الاستراتيجية للجامعة وتغطي التعليم والبحث وخدمة المجتمع." },
                    { 2308, "Common", "faculty_science", "9.1.1", 476, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 2309, "DepartmentSpecific", "faculty_science", "6.2 / 8.1", 477, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 2310, "Common", "faculty_science", "4.1", 478, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 2311, "Common", "faculty_science", "6.1", 479, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
                    { 2312, "Common", "faculty_science", "6.1", 480, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر الأكاديمية والتشغيلية والمخبرية في الكلية ووضع خطط وقائية للسيطرة عليها." },
                    { 2313, "DepartmentSpecific", "faculty_science", "8.1 / 9.1", 481, "البحث العلمي", "الخطة البحثية للأقسام ← تشجيع ومتابعة نشر الأبحاث المحكمة ← المؤتمرات والندوات العلمية ← رصد الإنتاج البحثي : التحقق من متابعة الكلية للنشاط البحثي لأعضاء هيئة التدريس، ونشر الأبحاث في قواعد البيانات العالمية (Scopus/WoS)، والمشاركات العلمية." },
                    { 2314, "Common", "faculty_science", "8.5.1 / 9.1.2", 482, "متابعة الخريجين", "حصر خريجي الكلية ← التواصل واللقاءات المهنية ← رصد نسب التوظيف ← استطلاع رأي الخريجين وأرباب العمل : التحقق من متابعة الكلية لخريجيها وإشراكهم مع أرباب العمل في تطوير الخطط والبرامج الدراسية." },
                    { 2315, "DepartmentSpecific", "faculty_science", "8.5.1", 483, "التعليم الإلكتروني", "رفع خطة ومحتوى المساق على المنصة ← الواجبات والأنشطة التفاعلية ← متابعة تفاعل الطلبة والمدرسين : التحقق من توظيف منصة التعلم الإلكتروني بفاعلية في كافة مساقات الكلية ومتابعة التزام المدرسين بمعايير المحتوى الإلكتروني." },
                    { 2316, "DepartmentSpecific", "faculty_science", "8.3", 484, "آلية تصميم وتطوير البرامج الدراسية", "دراسة حاجة سوق العمل والمقارنة المرجعية ← صياغة مخرجات التعلم (PLOS) والخطة الدراسية ← إقرار القسم والكلية ← الاعتماد الرسمي والمراجعة الدورية : التحقق من أن تصميم البرامج الدراسية أو تحديث الخطط الدراسية يتم وفق منهجية علمية تشارك أصحاب العلاقة وتغطي معايير الاعتماد." },
                    { 2317, "DepartmentSpecific", "faculty_science", "8.5.1", 485, "آلية طرح المساقات في الفصول الدراسية", "دراسة إحصائيات الطلبة والخطط الإرشادية ← إعداد الجدول الدراسي وتوزيع الأعباء التدريسية حسب التخصص ← إقرار القسم والكلية ← إرسال الجدول للقبول والتسجيل : التحقق من التخطيط السليم لطرح المساقات وتوزيعها على أعضاء هيئة التدريس وفق تخصصاتهم الدقيقة ونصابهم التدريسي." },
                    { 2318, "DepartmentSpecific", "faculty_science", "8.5.1 / 8.6", 486, "آلية إعداد الامتحانات ورصد النتائج", "إعداد أسئلة الامتحان وفق جدول المواصفات ومخرجات التعلم ← التدقيق والاعتماد من رئيس القسم/منسق المادة ← ضبط المراقبات والتصحيح ← تدقيق ورصد العلامات : التحقق من جودة وعدالة الامتحانات وارتباطها بمخرجات التعلم، وضبط إجراءات المراقبة والتصحيح والمراجعة قبل إعلان ورصد النتائج." },
                    { 2319, "DepartmentSpecific", "faculty_science", "9.1.1 / 9.1.3", 487, "تحليل النتائج إحصائيًا", "استخراج التوزيع التكراري للعلامات ونسب النجاح والرسوب ← قياس تحقق مخرجات التعلم ← مناقشة التحليل في القسم ← خطة تحسين المساق : التحقق من إجراء تحليل إحصائي لنتائج الطلبة ومخرجات التعلم في نهاية كل فصل دراسي واتخاذ إجراءات لمعالجة التضخم أو التدني." },
                    { 2320, "DepartmentSpecific", "faculty_science", "7.1.5", 488, "آلية إدارة معايرة أجهزة الفحص والقياس", "حصر أجهزة المختبرات ← جدول الصيانة الوقائية والمعايرة الدورية ← فحص الدقة وإصدار شهادة المعايرة ← وضع ملصق حالة المعايرة: (خاص بالكليات العلمية والطبية) التحقق من صيانة ومعايرة أجهزة المختبرات العلمية والطبية لضمان دقة النتائج وسلامة التجارب." },
                    { 2321, "DepartmentSpecific", "faculty_science", "7.1.4 / 8.5.1", 489, "السلامة العامة ومكافحة العدوى", "أدلة السلامة المخبرية (MSDS) ← توفير معدات الوقاية والطوارئ ← بروتوكول التعقيم ومكافحة العدوى ← التخلص الآمن من النفايات الطبية/الكيميائية: (خاص بالكليات العلمية والطبية) التحقق من تطبيق إجراءات السلامة الحيوية والكيميائية ومكافحة العدوى وإدارة النفايات الخطرة في المختبرات والعيادات التعليمية." },
                    { 2322, "Common", "faculty_science", "9.1.2", 490, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانات (تقييم المدرس والمساق، رضا الطالب العام) ← التحليل الإحصائي ← التغذية الراجعة ← خطة التحسين : التحقق من قياس رضا الطلبة وتقييمهم للمساقات والهيئة التدريسية والخدمات، وتحويل النتائج لخطط تحسين موثقة (مع معالجة الشكاوى الطلابية)." },
                    { 2400, "Common", "faculty_it", "5.3", 491, "الهيكل التنظيمي", "الإعداد ← الاعتماد الرسمي ← الإعلان والتعميم ← المطابقة الفعلية : التحقق من وجود هيكل تنظيمي معتمد للكلية يوضح العمادة، المجالس، الأقسام الأكاديمية، واللجان، ومطابقته للواقع الفعلي." },
                    { 2401, "Common", "faculty_it", "5.3 / 7.2", 492, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة (العميد، نائب/مساعد العميد، رؤساء الأقسام، أعضاء هيئة التدريس، مشرفي المختبرات، الإداريين) وموقعة بالعلم." },
                    { 2402, "Common", "faculty_it", "5.2", 493, "سياسة ادارة المؤسسات التعليمية", "الإعلان والنشر في الكلية ← التوعية والاستيعاب ← التطبيق في التدريس والتقييم : التحقق من إعلان سياسة نظام إدارة المؤسسات التعليمية (ورؤية ورسالة وأهداف الكلية) ومعرفة الكادر والطلبة بها." },
                    { 2403, "Common", "faculty_it", "7.1.4 / 8.5.3", 494, "بيئة العمل (سلامة عامة وخدمات ذوي الاحتياجات الخاصة ...)", "تفقد القاعات والمختبرات والمرافق ← تطبيق شروط السلامة العامة ← توفير التسهيلات الأكاديمية والبيئية لذوي الاحتياجات الخاصة : التحقق من جاهزية القاعات التدريسية والمختبرات والمكاتب وتوافر متطلبات السلامة وتسهيلات الطلبة ذوي الإعاقة." },
                    { 2404, "Common", "faculty_it", "7.5.2 / 7.5.3", 495, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النماذج السارية ← الفهرسة والأرشفة الآمنة ← مدة الحفظ : التحقق من التزام العمادة والأقسام الأكاديمية بضبط الوثائق وحفظ السجلات (محاضر المجالس، ملفات المساقات، ملفات الإرشاد) وفق نظام الجودة." },
                    { 2405, "Common", "faculty_it", "7.2", 496, "التدريب والكفاءة", "حصر الاحتياجات التدريبية (للكادر الأكاديمي والإداري والفني) ← خطة التدريب ← المشاركة الفعلية ← قياس أثر التدريب : التحقق من تأهيل وتدريب أعضاء هيئة التدريس ومشرفي المختبرات والإداريين في الكلية وتقييم انعكاس التدريب على أدائهم." },
                    { 2406, "Common", "faculty_it", "6.2", 497, "هدف الجودة", "صياغة أهداف ذكية للكلية والأقسام ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للكلية ومنسجمة مع أهداف الجامعة، ومتابعة نسب تحققها." },
                    { 2407, "Common", "faculty_it", "4.1 / 6.2", 498, "الخطة الاستراتيجية", "إعداد خطة الكلية الاستراتيجية المتوافقة مع استراتيجية الجامعة ← الاعتماد ← المراجعة الدورية : التحقق من وجود خطة استراتيجية معتمدة للكلية تنبثق من الخطة الاستراتيجية للجامعة وتغطي التعليم والبحث وخدمة المجتمع." },
                    { 2408, "Common", "faculty_it", "9.1.1", 499, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 2409, "DepartmentSpecific", "faculty_it", "6.2 / 8.1", 500, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 2410, "Common", "faculty_it", "4.1", 501, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 2411, "Common", "faculty_it", "6.1", 502, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
