                    { 2608, "Common", "faculty_graduate_studies", "9.1.1", 545, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 2609, "DepartmentSpecific", "faculty_graduate_studies", "6.2 / 8.1", 546, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 2610, "Common", "faculty_graduate_studies", "4.1", 547, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 2611, "Common", "faculty_graduate_studies", "6.1", 548, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
