                    { 2613, "DepartmentSpecific", "faculty_graduate_studies", "8.1 / 9.1", 550, "البحث العلمي", "الخطة البحثية للأقسام ← تشجيع ومتابعة نشر الأبحاث المحكمة ← المؤتمرات والندوات العلمية ← رصد الإنتاج البحثي : التحقق من متابعة الكلية للنشاط البحثي لأعضاء هيئة التدريس، ونشر الأبحاث في قواعد البيانات العالمية (Scopus/WoS)، والمشاركات العلمية." },
                    { 2614, "Common", "faculty_graduate_studies", "8.5.1 / 9.1.2", 551, "متابعة الخريجين", "حصر خريجي الكلية ← التواصل واللقاءات المهنية ← رصد نسب التوظيف ← استطلاع رأي الخريجين وأرباب العمل : التحقق من متابعة الكلية لخريجيها وإشراكهم مع أرباب العمل في تطوير الخطط والبرامج الدراسية." },
                    { 2615, "DepartmentSpecific", "faculty_graduate_studies", "8.5.1", 552, "التعليم الإلكتروني", "رفع خطة ومحتوى المساق على المنصة ← الواجبات والأنشطة التفاعلية ← متابعة تفاعل الطلبة والمدرسين : التحقق من توظيف منصة التعلم الإلكتروني بفاعلية في كافة مساقات الكلية ومتابعة التزام المدرسين بمعايير المحتوى الإلكتروني." },
                    { 2616, "DepartmentSpecific", "faculty_graduate_studies", "8.3", 553, "آلية تصميم وتطوير البرامج الدراسية", "دراسة حاجة سوق العمل والمقارنة المرجعية ← صياغة مخرجات التعلم (PLOS) والخطة الدراسية ← إقرار القسم والكلية ← الاعتماد الرسمي والمراجعة الدورية : التحقق من أن تصميم البرامج الدراسية أو تحديث الخطط الدراسية يتم وفق منهجية علمية تشارك أصحاب العلاقة وتغطي معايير الاعتماد." },
                    { 2617, "DepartmentSpecific", "faculty_graduate_studies", "8.5.1", 554, "آلية طرح المساقات في الفصول الدراسية", "دراسة إحصائيات الطلبة والخطط الإرشادية ← إعداد الجدول الدراسي وتوزيع الأعباء التدريسية حسب التخصص ← إقرار القسم والكلية ← إرسال الجدول للقبول والتسجيل : التحقق من التخطيط السليم لطرح المساقات وتوزيعها على أعضاء هيئة التدريس وفق تخصصاتهم الدقيقة ونصابهم التدريسي." },
                    { 2618, "DepartmentSpecific", "faculty_graduate_studies", "8.5.1 / 8.6", 555, "آلية إعداد الامتحانات ورصد النتائج", "إعداد أسئلة الامتحان وفق جدول المواصفات ومخرجات التعلم ← التدقيق والاعتماد من رئيس القسم/منسق المادة ← ضبط المراقبات والتصحيح ← تدقيق ورصد العلامات : التحقق من جودة وعدالة الامتحانات وارتباطها بمخرجات التعلم، وضبط إجراءات المراقبة والتصحيح والمراجعة قبل إعلان ورصد النتائج." },
                    { 2619, "DepartmentSpecific", "faculty_graduate_studies", "9.1.1 / 9.1.3", 556, "تحليل النتائج إحصائيًا", "استخراج التوزيع التكراري للعلامات ونسب النجاح والرسوب ← قياس تحقق مخرجات التعلم ← مناقشة التحليل في القسم ← خطة تحسين المساق : التحقق من إجراء تحليل إحصائي لنتائج الطلبة ومخرجات التعلم في نهاية كل فصل دراسي واتخاذ إجراءات لمعالجة التضخم أو التدني." },
                    { 2622, "Common", "faculty_graduate_studies", "9.1.2", 557, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانات (تقييم المدرس والمساق، رضا الطالب العام) ← التحليل الإحصائي ← التغذية الراجعة ← خطة التحسين : التحقق من قياس رضا الطلبة وتقييمهم للمساقات والهيئة التدريسية والخدمات، وتحويل النتائج لخطط تحسين موثقة (مع معالجة الشكاوى الطلابية)." },
                    { 2700, "Common", "faculty_technical", "5.3", 558, "الهيكل التنظيمي", "الإعداد ← الاعتماد الرسمي ← الإعلان والتعميم ← المطابقة الفعلية : التحقق من وجود هيكل تنظيمي معتمد للكلية يوضح العمادة، المجالس، الأقسام الأكاديمية، واللجان، ومطابقته للواقع الفعلي." },
                    { 2701, "Common", "faculty_technical", "5.3 / 7.2", 559, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة (العميد، نائب/مساعد العميد، رؤساء الأقسام، أعضاء هيئة التدريس، مشرفي المختبرات، الإداريين) وموقعة بالعلم." },
                    { 2702, "Common", "faculty_technical", "5.2", 560, "سياسة ادارة المؤسسات التعليمية", "الإعلان والنشر في الكلية ← التوعية والاستيعاب ← التطبيق في التدريس والتقييم : التحقق من إعلان سياسة نظام إدارة المؤسسات التعليمية (ورؤية ورسالة وأهداف الكلية) ومعرفة الكادر والطلبة بها." },
                    { 2703, "Common", "faculty_technical", "7.1.4 / 8.5.3", 561, "بيئة العمل (سلامة عامة وخدمات ذوي الاحتياجات الخاصة ...)", "تفقد القاعات والمختبرات والمرافق ← تطبيق شروط السلامة العامة ← توفير التسهيلات الأكاديمية والبيئية لذوي الاحتياجات الخاصة : التحقق من جاهزية القاعات التدريسية والمختبرات والمكاتب وتوافر متطلبات السلامة وتسهيلات الطلبة ذوي الإعاقة." },
                    { 2704, "Common", "faculty_technical", "7.5.2 / 7.5.3", 562, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النماذج السارية ← الفهرسة والأرشفة الآمنة ← مدة الحفظ : التحقق من التزام العمادة والأقسام الأكاديمية بضبط الوثائق وحفظ السجلات (محاضر المجالس، ملفات المساقات، ملفات الإرشاد) وفق نظام الجودة." },
                    { 2705, "Common", "faculty_technical", "7.2", 563, "التدريب والكفاءة", "حصر الاحتياجات التدريبية (للكادر الأكاديمي والإداري والفني) ← خطة التدريب ← المشاركة الفعلية ← قياس أثر التدريب : التحقق من تأهيل وتدريب أعضاء هيئة التدريس ومشرفي المختبرات والإداريين في الكلية وتقييم انعكاس التدريب على أدائهم." },
                    { 2706, "Common", "faculty_technical", "6.2", 564, "هدف الجودة", "صياغة أهداف ذكية للكلية والأقسام ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للكلية ومنسجمة مع أهداف الجامعة، ومتابعة نسب تحققها." },
                    { 2707, "Common", "faculty_technical", "4.1 / 6.2", 565, "الخطة الاستراتيجية", "إعداد خطة الكلية الاستراتيجية المتوافقة مع استراتيجية الجامعة ← الاعتماد ← المراجعة الدورية : التحقق من وجود خطة استراتيجية معتمدة للكلية تنبثق من الخطة الاستراتيجية للجامعة وتغطي التعليم والبحث وخدمة المجتمع." },
                    { 2708, "Common", "faculty_technical", "9.1.1", 566, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 2709, "DepartmentSpecific", "faculty_technical", "6.2 / 8.1", 567, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 2710, "Common", "faculty_technical", "4.1", 568, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 2711, "Common", "faculty_technical", "6.1", 569, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
                    { 2712, "Common", "faculty_technical", "6.1", 570, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر الأكاديمية والتشغيلية والمخبرية في الكلية ووضع خطط وقائية للسيطرة عليها." },
                    { 2713, "DepartmentSpecific", "faculty_technical", "8.1 / 9.1", 571, "البحث العلمي", "الخطة البحثية للأقسام ← تشجيع ومتابعة نشر الأبحاث المحكمة ← المؤتمرات والندوات العلمية ← رصد الإنتاج البحثي : التحقق من متابعة الكلية للنشاط البحثي لأعضاء هيئة التدريس، ونشر الأبحاث في قواعد البيانات العالمية (Scopus/WoS)، والمشاركات العلمية." },
                    { 2714, "Common", "faculty_technical", "8.5.1 / 9.1.2", 572, "متابعة الخريجين", "حصر خريجي الكلية ← التواصل واللقاءات المهنية ← رصد نسب التوظيف ← استطلاع رأي الخريجين وأرباب العمل : التحقق من متابعة الكلية لخريجيها وإشراكهم مع أرباب العمل في تطوير الخطط والبرامج الدراسية." },
                    { 2715, "DepartmentSpecific", "faculty_technical", "8.5.1", 573, "التعليم الإلكتروني", "رفع خطة ومحتوى المساق على المنصة ← الواجبات والأنشطة التفاعلية ← متابعة تفاعل الطلبة والمدرسين : التحقق من توظيف منصة التعلم الإلكتروني بفاعلية في كافة مساقات الكلية ومتابعة التزام المدرسين بمعايير المحتوى الإلكتروني." },
                    { 2716, "DepartmentSpecific", "faculty_technical", "8.3", 574, "آلية تصميم وتطوير البرامج الدراسية", "دراسة حاجة سوق العمل والمقارنة المرجعية ← صياغة مخرجات التعلم (PLOS) والخطة الدراسية ← إقرار القسم والكلية ← الاعتماد الرسمي والمراجعة الدورية : التحقق من أن تصميم البرامج الدراسية أو تحديث الخطط الدراسية يتم وفق منهجية علمية تشارك أصحاب العلاقة وتغطي معايير الاعتماد." },
                    { 2717, "DepartmentSpecific", "faculty_technical", "8.5.1", 575, "آلية طرح المساقات في الفصول الدراسية", "دراسة إحصائيات الطلبة والخطط الإرشادية ← إعداد الجدول الدراسي وتوزيع الأعباء التدريسية حسب التخصص ← إقرار القسم والكلية ← إرسال الجدول للقبول والتسجيل : التحقق من التخطيط السليم لطرح المساقات وتوزيعها على أعضاء هيئة التدريس وفق تخصصاتهم الدقيقة ونصابهم التدريسي." },
                    { 2718, "DepartmentSpecific", "faculty_technical", "8.5.1 / 8.6", 576, "آلية إعداد الامتحانات ورصد النتائج", "إعداد أسئلة الامتحان وفق جدول المواصفات ومخرجات التعلم ← التدقيق والاعتماد من رئيس القسم/منسق المادة ← ضبط المراقبات والتصحيح ← تدقيق ورصد العلامات : التحقق من جودة وعدالة الامتحانات وارتباطها بمخرجات التعلم، وضبط إجراءات المراقبة والتصحيح والمراجعة قبل إعلان ورصد النتائج." },
                    { 2719, "DepartmentSpecific", "faculty_technical", "9.1.1 / 9.1.3", 577, "تحليل النتائج إحصائيًا", "استخراج التوزيع التكراري للعلامات ونسب النجاح والرسوب ← قياس تحقق مخرجات التعلم ← مناقشة التحليل في القسم ← خطة تحسين المساق : التحقق من إجراء تحليل إحصائي لنتائج الطلبة ومخرجات التعلم في نهاية كل فصل دراسي واتخاذ إجراءات لمعالجة التضخم أو التدني." },
                    { 2720, "DepartmentSpecific", "faculty_technical", "7.1.5", 578, "آلية إدارة معايرة أجهزة الفحص والقياس", "حصر أجهزة المختبرات ← جدول الصيانة الوقائية والمعايرة الدورية ← فحص الدقة وإصدار شهادة المعايرة ← وضع ملصق حالة المعايرة: (خاص بالكليات العلمية والطبية) التحقق من صيانة ومعايرة أجهزة المختبرات العلمية والطبية لضمان دقة النتائج وسلامة التجارب." },
                    { 2721, "DepartmentSpecific", "faculty_technical", "7.1.4 / 8.5.1", 579, "السلامة العامة ومكافحة العدوى", "أدلة السلامة المخبرية (MSDS) ← توفير معدات الوقاية والطوارئ ← بروتوكول التعقيم ومكافحة العدوى ← التخلص الآمن من النفايات الطبية/الكيميائية: (خاص بالكليات العلمية والطبية) التحقق من تطبيق إجراءات السلامة الحيوية والكيميائية ومكافحة العدوى وإدارة النفايات الخطرة في المختبرات والعيادات التعليمية." },
                    { 2722, "Common", "faculty_technical", "9.1.2", 580, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانات (تقييم المدرس والمساق، رضا الطالب العام) ← التحليل الإحصائي ← التغذية الراجعة ← خطة التحسين : التحقق من قياس رضا الطلبة وتقييمهم للمساقات والهيئة التدريسية والخدمات، وتحويل النتائج لخطط تحسين موثقة (مع معالجة الشكاوى الطلابية)." }
                });

