            migrationBuilder.InsertData(
                table: "AuditItems",
                columns: new[] { "Id", "Category", "DepartmentId", "IsoReference", "SortOrder", "Title", "Workflow" },
                values: new object[,]
                {
                    { 900, "Common", "faculties", "5.3", 169, "الهيكل التنظيمي", "الإعداد ← الاعتماد الرسمي ← الإعلان والتعميم ← المطابقة الفعلية : التحقق من وجود هيكل تنظيمي معتمد للكلية يوضح العمادة، المجالس، الأقسام الأكاديمية، واللجان، ومطابقته للواقع الفعلي." },
                    { 901, "Common", "faculties", "5.3 / 7.2", 170, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة (العميد، نائب/مساعد العميد، رؤساء الأقسام، أعضاء هيئة التدريس، مشرفي المختبرات، الإداريين) وموقعة بالعلم." },
                    { 902, "Common", "faculties", "5.2", 171, "سياسة ادارة المؤسسات التعليمية", "الإعلان والنشر في الكلية ← التوعية والاستيعاب ← التطبيق في التدريس والتقييم : التحقق من إعلان سياسة نظام إدارة المؤسسات التعليمية (ورؤية ورسالة وأهداف الكلية) ومعرفة الكادر والطلبة بها." },
                    { 903, "Common", "faculties", "7.1.4 / 8.5.3", 172, "بيئة العمل (سلامة عامة وخدمات ذوي الاحتياجات الخاصة ...)", "تفقد القاعات والمختبرات والمرافق ← تطبيق شروط السلامة العامة ← توفير التسهيلات الأكاديمية والبيئية لذوي الاحتياجات الخاصة : التحقق من جاهزية القاعات التدريسية والمختبرات والمكاتب وتوافر متطلبات السلامة وتسهيلات الطلبة ذوي الإعاقة." },
                    { 904, "Common", "faculties", "7.5.2 / 7.5.3", 173, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النماذج السارية ← الفهرسة والأرشفة الآمنة ← مدة الحفظ : التحقق من التزام العمادة والأقسام الأكاديمية بضبط الوثائق وحفظ السجلات (محاضر المجالس، ملفات المساقات، ملفات الإرشاد) وفق نظام الجودة." },
                    { 905, "Common", "faculties", "7.2", 174, "التدريب والكفاءة", "حصر الاحتياجات التدريبية (للكادر الأكاديمي والإداري والفني) ← خطة التدريب ← المشاركة الفعلية ← قياس أثر التدريب : التحقق من تأهيل وتدريب أعضاء هيئة التدريس ومشرفي المختبرات والإداريين في الكلية وتقييم انعكاس التدريب على أدائهم." },
                    { 906, "Common", "faculties", "6.2", 175, "هدف الجودة", "صياغة أهداف ذكية للكلية والأقسام ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للكلية ومنسجمة مع أهداف الجامعة، ومتابعة نسب تحققها." },
                    { 907, "Common", "faculties", "4.1 / 6.2", 176, "الخطة الاستراتيجية", "إعداد خطة الكلية الاستراتيجية المتوافقة مع استراتيجية الجامعة ← الاعتماد ← المراجعة الدورية : التحقق من وجود خطة استراتيجية معتمدة للكلية تنبثق من الخطة الاستراتيجية للجامعة وتغطي التعليم والبحث وخدمة المجتمع." },
                    { 908, "Common", "faculties", "9.1.1", 177, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 909, "DepartmentSpecific", "faculties", "6.2 / 8.1", 178, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 910, "Common", "faculties", "4.1", 179, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 911, "Common", "faculties", "6.1", 180, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
                    { 912, "Common", "faculties", "6.1", 181, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر الأكاديمية والتشغيلية والمخبرية في الكلية ووضع خطط وقائية للسيطرة عليها." },
                    { 913, "DepartmentSpecific", "faculties", "8.1 / 9.1", 182, "البحث العلمي", "الخطة البحثية للأقسام ← تشجيع ومتابعة نشر الأبحاث المحكمة ← المؤتمرات والندوات العلمية ← رصد الإنتاج البحثي : التحقق من متابعة الكلية للنشاط البحثي لأعضاء هيئة التدريس، ونشر الأبحاث في قواعد البيانات العالمية (Scopus/WoS)، والمشاركات العلمية." },
                    { 914, "Common", "faculties", "8.5.1 / 9.1.2", 183, "متابعة الخريجين", "حصر خريجي الكلية ← التواصل واللقاءات المهنية ← رصد نسب التوظيف ← استطلاع رأي الخريجين وأرباب العمل : التحقق من متابعة الكلية لخريجيها وإشراكهم مع أرباب العمل في تطوير الخطط والبرامج الدراسية." },
                    { 915, "DepartmentSpecific", "faculties", "8.5.1", 184, "التعليم الإلكتروني", "رفع خطة ومحتوى المساق على المنصة ← الواجبات والأنشطة التفاعلية ← متابعة تفاعل الطلبة والمدرسين : التحقق من توظيف منصة التعلم الإلكتروني بفاعلية في كافة مساقات الكلية ومتابعة التزام المدرسين بمعايير المحتوى الإلكتروني." },
                    { 916, "DepartmentSpecific", "faculties", "8.3", 185, "آلية تصميم وتطوير البرامج الدراسية", "دراسة حاجة سوق العمل والمقارنة المرجعية ← صياغة مخرجات التعلم (PLOS) والخطة الدراسية ← إقرار القسم والكلية ← الاعتماد الرسمي والمراجعة الدورية : التحقق من أن تصميم البرامج الدراسية أو تحديث الخطط الدراسية يتم وفق منهجية علمية تشارك أصحاب العلاقة وتغطي معايير الاعتماد." },
                    { 917, "DepartmentSpecific", "faculties", "8.5.1", 186, "آلية طرح المساقات في الفصول الدراسية", "دراسة إحصائيات الطلبة والخطط الإرشادية ← إعداد الجدول الدراسي وتوزيع الأعباء التدريسية حسب التخصص ← إقرار القسم والكلية ← إرسال الجدول للقبول والتسجيل : التحقق من التخطيط السليم لطرح المساقات وتوزيعها على أعضاء هيئة التدريس وفق تخصصاتهم الدقيقة ونصابهم التدريسي." },
                    { 918, "DepartmentSpecific", "faculties", "8.5.1 / 8.6", 187, "آلية إعداد الامتحانات ورصد النتائج", "إعداد أسئلة الامتحان وفق جدول المواصفات ومخرجات التعلم ← التدقيق والاعتماد من رئيس القسم/منسق المادة ← ضبط المراقبات والتصحيح ← تدقيق ورصد العلامات : التحقق من جودة وعدالة الامتحانات وارتباطها بمخرجات التعلم، وضبط إجراءات المراقبة والتصحيح والمراجعة قبل إعلان ورصد النتائج." },
                    { 919, "DepartmentSpecific", "faculties", "9.1.1 / 9.1.3", 188, "تحليل النتائج إحصائيًا", "استخراج التوزيع التكراري للعلامات ونسب النجاح والرسوب ← قياس تحقق مخرجات التعلم ← مناقشة التحليل في القسم ← خطة تحسين المساق : التحقق من إجراء تحليل إحصائي لنتائج الطلبة ومخرجات التعلم في نهاية كل فصل دراسي واتخاذ إجراءات لمعالجة التضخم أو التدني." },
                    { 920, "DepartmentSpecific", "faculties", "7.1.5", 189, "آلية إدارة معايرة أجهزة الفحص والقياس **", "حصر أجهزة المختبرات ← جدول الصيانة الوقائية والمعايرة الدورية ← فحص الدقة وإصدار شهادة المعايرة ← وضع ملصق حالة المعايرة: (خاص بالكليات العلمية والطبية) التحقق من صيانة ومعايرة أجهزة المختبرات العلمية والطبية لضمان دقة النتائج وسلامة التجارب." },
                    { 921, "DepartmentSpecific", "faculties", "7.1.4 / 8.5.1", 190, "السلامة العامة ومكافحة العدوى **", "أدلة السلامة المخبرية (MSDS) ← توفير معدات الوقاية والطوارئ ← بروتوكول التعقيم ومكافحة العدوى ← التخلص الآمن من النفايات الطبية/الكيميائية: (خاص بالكليات العلمية والطبية) التحقق من تطبيق إجراءات السلامة الحيوية والكيميائية ومكافحة العدوى وإدارة النفايات الخطرة في المختبرات والعيادات التعليمية." },
                    { 922, "Common", "faculties", "9.1.2", 191, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانات (تقييم المدرس والمساق، رضا الطالب العام) ← التحليل الإحصائي ← التغذية الراجعة ← خطة التحسين : التحقق من قياس رضا الطلبة وتقييمهم للمساقات والهيئة التدريسية والخدمات، وتحويل النتائج لخطط تحسين موثقة (مع معالجة الشكاوى الطلابية)." }
                });

            migrationBuilder.InsertData(
